def assign_expense_tenants(apps, schema_editor):
    Tenant = apps.get_model('core', 'Tenant')
    Expense = apps.get_model('expenses', 'Expense')
    ExpenseCategory = apps.get_model('expenses', 'ExpenseCategory')
    database = schema_editor.connection.alias

    tenants = list(Tenant.objects.using(database).values_list('id', flat=True))
    if not tenants:
        return
    if len(tenants) == 1:
        tenant_id = tenants[0]
        Expense.objects.using(database).filter(tenant__isnull=True).update(
            tenant_id=tenant_id,
        )
        ExpenseCategory.objects.using(database).filter(
            tenant__isnull=True,
        ).update(tenant_id=tenant_id)
        return

    for expense in Expense.objects.using(database).filter(tenant__isnull=True):
        owner_ids = set()
        if expense.created_by_id and expense.created_by.tenant_id:
            owner_ids.add(expense.created_by.tenant_id)
        if expense.account_id and expense.account.tenant_id:
            owner_ids.add(expense.account.tenant_id)
        if expense.fund_id and expense.fund.tenant_id:
            owner_ids.add(expense.fund.tenant_id)
        _set_tenant(expense, owner_ids, f'La dépense {expense.pk}')

    for category in ExpenseCategory.objects.using(database).filter(tenant__isnull=True):
        tenant_ids = Expense.objects.using(database).filter(
            category_id=category.pk,
        ).values_list('tenant_id', flat=True).distinct()
        _set_tenant(category, tenant_ids, f'La catégorie de dépense {category.pk}')


